function createGame({canvas, ctx, input, api, assets}) {
    const width = canvas.width;
    const height = canvas.height;

    // Game State
    let phase = 'playing';
    let score = 0;
    let distance = 0;

    const player = {
        x: 400,
        y: 350,
        angle: -Math.PI / 2,
        speed: 0,
        accel: 400,
        decel: 250,
        maxSpeed: 450,
        turnSpeed: 3.5,
        width: 32,
        height: 48,
        friction: 0.96
    };

    const obstacles = [];
    const coins = [];
    const trackBounds = { minX: 0, maxX: 2000, minY: 0, maxY: 2000 };

    // Use string constants for keys to avoid KeyboardEvent dependency issues in some environments
    const KEYS = {
        UP: 'ArrowUp',
        DOWN: 'ArrowDown',
        LEFT: 'ArrowLeft',
        RIGHT: 'ArrowRight'
    };

    function initWorld() {
        obstacles.length = 0;
        coins.length = 0;
        score = 0;
        distance = 0;
        player.x = 400;
        player.y = 350;
        player.speed = 0;
        player.angle = -Math.PI / 2;

        for (let i = 0; i < 35; i++) {
            obstacles.push({
                x: Math.random() * 1800 + 100,
                y: Math.random() * 1800 + 100,
                size: 40 + Math.random() * 40
            });
        }
        for (let i = 0; i < 20; i++) {
            coins.push({
                x: Math.random() * 1800 + 100,
                y: Math.random() * 1800 + 100,
                collected: false
            });
        }
    }

    initWorld();

    return {
        update(dt) {
            if (phase !== 'playing') return;

            // Input Handling using input.keys map
            if (input.keys[KEYS.UP]) {
                player.speed += player.accel * dt;
            } else if (input.keys[KEYS.DOWN]) {
                player.speed -= player.decel * dt;
            } else {
                // Natural friction
                player.speed *= Math.pow(player.friction, dt * 60);
            }

            // Speed limits
            if (player.speed > player.maxSpeed) player.speed = player.maxSpeed;
            if (player.speed < -player.maxSpeed / 3) player.speed = -player.maxSpeed / 3;

            // Steering (only when moving)
            if (Math.abs(player.speed) > 20) {
                const turnDir = player.speed > 0 ? 1 : -1;
                if (input.keys[KEYS.LEFT]) player.angle -= player.turnSpeed * dt * turnDir;
                if (input.keys[KEYS.RIGHT]) player.angle += player.turnSpeed * dt * turnDir;
            }

            // Movement
            player.x += Math.cos(player.angle) * player.speed * dt;
            player.y += Math.sin(player.angle) * player.speed * dt;

            // Boundary check
            if (player.x < 0 || player.x > trackBounds.maxX || player.y < 0 || player.y > trackBounds.maxY) {
                phase = 'lost';
                api.finish('lost', 'You drove off the track!');
            }

            // Collision: Rocks
            obstacles.forEach(rock => {
                const dx = player.x - rock.x;
                const dy = player.y - rock.y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist < rock.size / 2 + 15) {
                    phase = 'lost';
                    api.finish('lost', 'You crashed into a rock!');
                }
            });

            // Collision: Coins
            coins.forEach(coin => {
                if (!coin.collected) {
                    const dx = player.x - coin.x;
                    const dy = player.y - coin.y;
                    const dist = Math.sqrt(dx * dx + dy * dy);
                    if (dist < 35) {
                        coin.collected = true;
                        score += 100;
                        api.sound(523.25, 0.1); // C5
                        api.sound(659.25, 0.1); // E5
                    }
                }
            });

            // Scoring/Progress
            distance = Math.floor(Math.sqrt(Math.pow(player.x - 400, 2) + Math.pow(player.y - 350, 2)) / 10);

            api.setHud({
                status: "Collect coins! Avoid rocks!",
                stats: [
                    { label: "Score", value: score },
                    { label: "Distance", value: distance }
                ]
            });

            if (score >= 1500) {
                phase = 'won';
                api.finish('won', 'Champion Racer!');
            }
        },

        render() {
            // Background (Grass)
            ctx.fillStyle = '#2d6a4f'; 
            ctx.fillRect(0, 0, width, height);

            ctx.save();
            // Camera follows player
            ctx.translate(width / 2 - player.x, height / 2 - player.y);

            // Draw Track (Asphalt)
            ctx.fillStyle = '#333';
            ctx.fillRect(0, 0, trackBounds.maxX, trackBounds.maxY);

            // Draw Track Edges/Lines
            ctx.strokeStyle = '#555';
            ctx.lineWidth = 10;
            ctx.strokeRect(0, 0, trackBounds.maxX, trackBounds.maxY);

            // Draw Coins
            coins.forEach(coin => {
                if (!coin.collected) {
                    ctx.drawImage(assets.image('coin'), coin.x - 24, coin.y - 24, 48, 48);
                }
            });

            // Draw Rocks
            obstacles.forEach(rock => {
                ctx.drawImage(assets.image('rock'), rock.x - rock.size/2, rock.y - rock.size/2, rock.size, rock.size);
            });

            // Draw Player
            ctx.save();
            ctx.translate(player.x, player.y);
            ctx.rotate(player.angle + Math.PI / 2);
            ctx.drawImage(assets.image('car'), -player.width / 2, -player.height / 2, player.width, player.height);
            ctx.restore();

            ctx.restore();
        },

        inspect() {
            return {
                phase,
                metrics: {
                    score,
                    distance,
                    x: player.x,
                    y: player.y,
                    speed: player.speed
                }
            };
        }
    };
}
